import os
from decimal import Decimal
from database_client import get_dynamodb_resource

def conditional_update(document_id: str, table_name: str, updates: dict, key_field: str = "id", expected_version_field: str = None, expected_version_value: int = None, region_name: str = None):
    region_name = region_name or os.environ.get("AWS_REGION", "us-east-1")
    dynamodb = get_dynamodb_resource(region_name=region_name)
    table = dynamodb.Table(table_name)

    update_expression_parts = []
    expression_attribute_values = {}
    expression_attribute_names = {}

    for k, v in updates.items():
        # DynamoDB does not allow dots in attribute names for ExpressionAttributeNames. Replace with placeholder.
        attr_name_placeholder = f"#attr_{k.replace('.', '_')}"
        update_expression_parts.append(f"{attr_name_placeholder} = :{k}")
        expression_attribute_values[f":{k}"] = v
        expression_attribute_names[attr_name_placeholder] = k

    update_expression = "SET " + ", ".join(update_expression_parts)

    condition_expression = None
    if expected_version_field and expected_version_value is not None:
        # Ensure the version field is also properly named in the expression
        version_attr_name_placeholder = f"#attr_{expected_version_field.replace('.', '_')}"
        condition_expression = f"{version_attr_name_placeholder} = :expected_version_val"
        expression_attribute_values[":expected_version_val"] = expected_version_value
        expression_attribute_names[version_attr_name_placeholder] = expected_version_field

    update_kwargs = {
        "Key": {key_field: document_id},
        "UpdateExpression": update_expression,
        "ExpressionAttributeValues": expression_attribute_values,
        "ReturnValues": "UPDATED_NEW"
    }

    if expression_attribute_names:
        update_kwargs["ExpressionAttributeNames"] = expression_attribute_names

    if condition_expression:
        update_kwargs["ConditionExpression"] = condition_expression

    try:
        response = table.update_item(**update_kwargs)
        return response.get("Attributes")
    except Exception as e:
        print(f"Conditional update failed: {e}")
        return None

import os
from database_client import get_comprehend_client
from database_models import Document

def check_text_safety(document: Document, text_field: str, region_name: str = None):
    region_name = region_name or os.environ.get("AWS_REGION", "us-east-1")
    comprehend = get_comprehend_client(region_name=region_name)

    text_to_analyze = document.get(text_field, "")
    if not text_to_analyze:
        return {"safety_check": "No text field to check for safety."}

    # Detect dominant language first
    language_response = comprehend.detect_dominant_language(Text=text_to_analyze)
    languages = language_response.get("Languages", [])
    dominant_language = languages[0]["LanguageCode"] if languages else "en"

    # Using PII detection as a form of safety check
    pii_response = comprehend.detect_pii_entities(
        Text=text_to_analyze,
        LanguageCode=dominant_language
    )

    unsafe_content_detected = False
    pii_entities = pii_response.get("Entities", [])
    if pii_entities:
        unsafe_content_detected = True

    safety_report = {
        "language": dominant_language,
        "contains_pii": unsafe_content_detected,
        "pii_entities": [{
            "type": entity["Type"],
            "score": entity["Score"],
            "text": text_to_analyze[entity["BeginOffset"]:entity["EndOffset"]]
        } for entity in pii_entities]
    }

    return {"safety_check": safety_report}

import os
from database_client import get_translate_client
from database_models import Document

def translate_record_field(document: Document, field_to_translate: str, target_language_code: str, source_language_code: str = "auto", region_name: str = None):
    region_name = region_name or os.environ.get("AWS_REGION", "us-east-1")
    translate_client = get_translate_client(region_name=region_name)

    text_to_translate = document.get(field_to_translate, "")
    if not text_to_translate:
        return {"translated_field": "", "source_language": ""}

    try:
        response = translate_client.translate_text(
            Text=text_to_translate,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code
        )
        translated_text = response.get("TranslatedText", "")
        actual_source_language = response.get("SourceLanguageCode", source_language_code)

        return {"translated_field": translated_text, "source_language": actual_source_language}
    except Exception as e:
        print(f"Translation failed: {e}")
        return {"translated_field": text_to_translate, "source_language": source_language_code, "error": str(e)}
